  private isValidCreditCard(creditCard: string): boolean {
    return /^\d{16}$/.test(creditCard);
  }

  private isValidPhone(phone: string): boolean {
    return /^\d{1}-\d{3}-\d{3}$/.test(phone);
  }
}
